window.NARRATION = {"ci_a": {"dur": 22.72, "text": "Pressure shows how you actually lead. This is where you start to see the gap between instinct and intention. Take about 30 seconds on each of these. Write what actually went on inside you, rather than what you think should have happened. Only you can see what you write, and it's saved here so you can come back to it. Select Save on each one as you go, then select Next.", "sents": [[0.03, "Pressure shows how you actually lead.", 0], [2.93, "This is where you start to see the gap between instinct and intention.", 0], [7.35, "Take about 30 seconds on each of these.", 1], [9.97, "Write what actually went on inside you, rather than what you think should have happened.", 1], [14.69, "Only you can see what you write, and it's saved here so you can come back to it.", 1], [19.05, "Select Save on each one as you go, then select Next.", 2]], "v": "k1", "cues": [0.03, 7.35, 19.05]}, "ci_b": {"dur": 10.8, "text": "Now look at what you wrote and pick the pattern that's closest to it. There's no right answer. Naming a habit helps you catch it sooner next time, so pick the one that best reflects your experience.", "sents": [[0.01, "Now look at what you wrote and pick the pattern that's closest to it.", 0], [3.75, "There's no right answer.", 1], [5.23, "Naming a habit helps you catch it sooner next time, so pick the one that best reflects your experience.", 1]], "v": "k1", "cues": [0.01, 3.75]}, "ci_c": {"dur": 20.08, "text": "Now run the Foundation Reset. Say your five words, the ones you saved on the Foundation Reset screen. Ask yourself for two next-best steps. Pick the one you'll take in the next ten minutes. Then take one breath and answer the anchor on the last card. It takes about a minute and works best standing up, so do it now before you move on.", "sents": [[0, "Now run the Foundation Reset.", 0], [2.15, "Say your five words, the ones you saved on the Foundation Reset screen.", 1], [6.37, "Ask yourself for two next-best steps.", 1], [9.07, "Pick the one you'll take in the next ten minutes.", 1], [11.71, "Then take one breath and answer the anchor on the last card.", 1], [15.41, "It takes about a minute and works best standing up, so do it now before you move on.", 2]], "v": "k1", "cues": [0, 2.15, 15.41]}, "kc_retry": {"dur": 3.68, "text": "Not quite. Have another look, then try again.", "sents": [[0.05, "Not quite.", 0], [1.45, "Have another look, then try again.", 0]], "v": "v4l", "cues": [0.05]}, "n_5_0": {"dur": 9.84, "text": "Lesson 5 turns your goals into a plan with names and dates on it. It takes about 40 minutes here, then one core rep this week. Select Start Lesson.", "sents": [[0.01, "Lesson 5 turns your goals into a plan with names and dates on it.", 0], [4.75, "It takes about 40 minutes here, then one core rep this week.", 1], [8.39, "Select Start Lesson.", 1]], "v": "k1", "cues": [0.01, 4.75]}, "n_5_1": {"dur": 10.32, "text": "Read this moment. Does it sound familiar? A goal you can't start on Monday morning isn't ready yet. This lesson turns wishes into work you can start.", "sents": [[0.05, "Read this moment.", 0], [1.63, "Does it sound familiar?", 0], [3.27, "A goal you can't start on Monday morning isn't ready yet.", 1], [6.97, "This lesson turns wishes into work you can start.", 1]], "v": "v4l", "cues": [0.05, 3.27]}, "n_5_11": {"dur": 29.92, "text": "Every goal in Part 3 of your Scorecard answers these questions. Actions are the concrete steps you'll take every day or week. Resources are what you need: time, money, an introduction, or one piece of information. Your corner includes the people supporting you at work and at home and how often you'll check in with them. Set that rhythm now. Every goal gets a deadline and a celebration. The deadline date drives the work, and the celebration makes you want to pursue the next goal.", "sents": [[0, "Every goal in Part 3 of your Scorecard answers these questions.", 0], [4.45, "Actions are the concrete steps you'll take every day or week.", 1], [8.43, "Resources are what you need: time, money, an introduction, or one piece of information.", 1], [14.27, "Your corner includes the people supporting you at work and at home and how often you'll check in with them.", 2], [20.09, "Set that rhythm now.", 2], [21.93, "Every goal gets a deadline and a celebration.", 3], [25.07, "The deadline date drives the work, and the celebration makes you want to pursue the next goal.", 3]], "v": "k1", "cues": [0, 4.45, 14.27, 21.93]}, "n_5_12": {"dur": 7.6, "text": "Say your gap is the same as one of Lynn's: current industry knowledge. Choose the version you could start on Monday, and you'll hear why.", "sents": [[0, "Say your gap is the same as one of Lynn's: current industry knowledge.", 0], [4.37, "Choose the version you could start on Monday, and you'll hear why.", 1]], "v": "v4l", "cues": [0, 4.37]}, "n_5_12_o0": {"dur": 7.68, "text": "That's a wish. There's nothing to do on Monday morning and no way to know when you're done. Try the other option to compare.", "sents": [[0.03, "That's a wish.", 0], [1.57, "There's nothing to do on Monday morning and no way to know when you're done.", 0], [5.77, "Try the other option to compare.", 0]], "v": "v4l", "cues": [0.03]}, "n_5_12_o1": {"dur": 7.28, "text": "That's a SMART goal, and it builds alignment with your manager at the same time. You know exactly what to do next week.", "sents": [[0, "That's a SMART goal, and it builds alignment with your manager at the same time.", 0], [4.89, "You know exactly what to do next week.", 0]], "v": "k1", "cues": [0]}, "n_5_14": {"dur": 10.08, "text": "Time for the drill. This one puts you in a disagreement in front of other people. Press Play. The video pauses a few times so you can answer, and it resumes when you're done.", "sents": [[0.01, "Time for the drill.", 0], [1.59, "This one puts you in a disagreement in front of other people.", 0], [4.89, "Press Play.", 1], [5.97, "The video pauses a few times so you can answer, and it resumes when you're done.", 1]], "v": "k1", "cues": [0.01, 4.89]}, "n_5_15": {"dur": 37.28, "text": "This is the most useful Playbook week of the season. Your core rep is drill 5.2, which takes about 30 minutes: list what your vision needs from you, pick the two or three gaps that matter most, and write each one as a SMART goal. If you have more time, drill 5.1 takes that list further: everything your vision needs from you and from the people around you. When you can, build your plan in Part 3 of your Scorecard and start the weekly Scorecard check-in in Part 4. Set aside 15 minutes every week from now on. Run your core rep, then ask one person for feedback on your SMART goals.", "sents": [[0.01, "This is the most useful Playbook week of the season.", 0], [3.89, "Your core rep is drill 5.2, which takes about 30 minutes: list what your vision needs from you, pick the two or three gaps that matter most, and write each one as a SMART goal.", 0], [15.09, "If you have more time, drill 5.1 takes that list further: everything your vision needs from you and from the people around you.", 1], [23.19, "When you can, build your plan in Part 3 of your Scorecard and start the weekly Scorecard check-in in Part 4.", 2], [29.89, "Set aside 15 minutes every week from now on.", 2], [33.15, "Run your core rep, then ask one person for feedback on your SMART goals.", 3]], "v": "k1", "cues": [0.01, 15.09, 23.19, 33.15]}, "n_5_16": {"dur": 12.24, "text": "This lesson's Athleader Pro is Ryall Graber, the Wellness Catalyst. She's an IFBB Pro, and her story is about what peak performance costs when there's nothing underneath it. Press Play to hear from her.", "sents": [[0, "This lesson's Athleader Pro is Ryall Graber, the Wellness Catalyst.", 0], [4.57, "She's an IFBB Pro, and her story is about what peak performance costs when there's nothing underneath it.", 0], [11.01, "Press Play to hear from her.", 1]], "v": "v4l", "cues": [0, 11.01]}, "n_5_17": {"dur": 12.64, "text": "Ryall's drill is an energy audit, and it takes three minutes. Select Start the timer and work through each step as it lights up. When you've completed the drill or scheduled a time to run it, select the option that fits.", "sents": [[0, "Ryall's drill is an energy audit, and it takes three minutes.", 0], [4.05, "Select Start the timer and work through each step as it lights up.", 1], [8.09, "When you've completed the drill or scheduled a time to run it, select the option that fits.", 1]], "v": "k1", "cues": [0, 4.05]}, "n_5_19_q0": {"dur": 8.08, "text": "A few questions to check the main ideas. Which part of a SMART goal is missing from: get three mentors to review my plan?", "sents": [[0, "A few questions to check the main ideas.", 0], [2.75, "Which part of a SMART goal is missing from: get three mentors to review my plan?", 0]], "v": "v4l", "cues": [0]}, "n_5_19_q1": {"dur": 2.08, "text": "What made Lynn's plan hold?", "sents": [[0.05, "What made Lynn's plan hold?", 0]], "v": "v4l", "cues": [0.05]}, "n_5_19_q2": {"dur": 4.88, "text": "Last one. Which question does every goal in your Scorecard answer?", "sents": [[0.15, "Last one.", 0], [1.35, "Which question does every goal in your Scorecard answer?", 0]], "v": "v4l", "cues": [0.15]}, "n_5_19_w0": {"dur": 11.28, "text": "It's missing a time-bound element. Having three mentors review the plan is specific and measurable, and a plan review is relevant, but without a date it never becomes urgent.", "sents": [[0.05, "It's missing a time-bound element.", 0], [2.67, "Having three mentors review the plan is specific and measurable, and a plan review is relevant, but without a date it never becomes urgent.", 0]], "v": "k1", "cues": [0.05]}, "n_5_19_w1": {"dur": 6.64, "text": "Her home, her boss, and her team were all aligned with the plan. Personal readiness was only half of it.", "sents": [[0.03, "Her home, her boss, and her team were all aligned with the plan.", 0], [4.51, "Personal readiness was only half of it.", 0]], "v": "v4l", "cues": [0.03]}, "n_5_19_w2": {"dur": 7.04, "text": "Every goal names who's in your corner and how often you'll check in, along with actions, resources, and a deadline.", "sents": [[0, "Every goal names who's in your corner and how often you'll check in, along with actions, resources, and a deadline.", 0]], "v": "v4l", "cues": [0]}, "n_5_20": {"dur": 36.8, "text": "Before you go, a quick recap. Readiness has two halves: your own mindset, energy, and skills, and your alignment with your manager, your peers, your team, and home. A goal you can't start on Monday isn't ready. Make it specific, measurable, attainable, relevant, and time-bound. Every goal answers four questions: actions, resources, your corner, and a deadline with a celebration. That's Part 3 of your Scorecard. Select Download my answers for a Word document containing what you wrote today. Chapter 11 of the book is all about the 90-Day Way.", "sents": [[0.01, "Before you go, a quick recap.", 0], [2.51, "Readiness has two halves: your own mindset, energy, and skills, and your alignment with your manager, your peers, your team, and home.", 1], [11.83, "A goal you can't start on Monday isn't ready.", 2], [14.81, "Make it specific, measurable, attainable, relevant, and time-bound.", 2], [19.71, "Every goal answers four questions: actions, resources, your corner, and a deadline with a celebration.", 3], [26.97, "That's Part 3 of your Scorecard.", 3], [29.15, "Select Download my answers for a Word document containing what you wrote today.", 4], [33.51, "Chapter 11 of the book is all about the 90-Day Way.", 4]], "v": "k1", "cues": [0.01, 2.51, 11.83, 19.71, 29.15]}, "n_5_21": {"dur": 13.76, "text": "That's Lesson 5 done. One lesson to go, and you've built a plan you can start on Monday. This week, run your core rep, writing your SMART goals, and ask one person for feedback on them. Next time is the victory lap.", "sents": [[0.05, "That's Lesson 5 done.", 0], [1.99, "One lesson to go, and you've built a plan you can start on Monday.", 0], [5.95, "This week, run your core rep, writing your SMART goals, and ask one person for feedback on them.", 1], [11.81, "Next time is the victory lap.", 1]], "v": "k1", "cues": [0.05, 5.95]}, "n_5_3": {"dur": 6.08, "text": "A quick look back at Lesson 4. What does stress-testing a goal mean? This one isn't scored.", "sents": [[0, "A quick look back at Lesson 4.", 0], [2.23, "What does stress-testing a goal mean?", 1], [4.59, "This one isn't scored.", 1]], "v": "v4l", "cues": [0, 2.23]}, "n_5_4": {"dur": 20.48, "text": "This lesson is about writing goals you can start on Monday. You'll list what your vision needs from you and from the people around you. You'll find the two or three gaps that matter most and write each one as a SMART goal. Then you'll build the plan in Part 3 of your Scorecard, with actions, resources, a support team, and a deadline for every goal.", "sents": [[0, "This lesson is about writing goals you can start on Monday.", 0], [3.71, "You'll list what your vision needs from you and from the people around you.", 1], [7.79, "You'll find the two or three gaps that matter most and write each one as a SMART goal.", 2], [12.87, "Then you'll build the plan in Part 3 of your Scorecard, with actions, resources, a support team, and a deadline for every goal.", 3]], "v": "v4l", "cues": [0, 3.71, 7.79, 12.87]}, "n_5_7": {"dur": 32.08, "text": "Every plan needs two things in place, and most people only check the first. Personal readiness is your own state: whether you believe it's achievable, whether you have the energy for it, and which skills are missing. Lynn had the legal experience. Her gaps were managing people, managing budgets, and keeping up with her industry. Relational alignment is how you're set up with others: your manager, your peers, your team, and the people at home. Lynn's plan only worked once her spouse, her boss, and her team were all pulling the same way.", "sents": [[0.05, "Every plan needs two things in place, and most people only check the first.", 0], [5.13, "Personal readiness is your own state: whether you believe it's achievable, whether you have the energy for it, and which skills are missing.", 1], [12.81, "Lynn had the legal experience.", 1], [14.87, "Her gaps were managing people, managing budgets, and keeping up with her industry.", 1], [19.69, "Relational alignment is how you're set up with others: your manager, your peers, your team, and the people at home.", 2], [26.51, "Lynn's plan only worked once her spouse, her boss, and her team were all pulling the same way.", 2]], "v": "v4l", "cues": [0.05, 5.13, 19.69]}, "n_5_9": {"dur": 27.36, "text": "Here's Evan's goal from the video, built one letter at a time. It's specific: partnership proposals from qualified vendors. And it's measurable because he can count three proposals. It's attainable since 60 days is enough to run a small selection process. And it's relevant, because a technical partner is exactly what his online community needs. And it's time-bound: within 60 days. A goal like this tells you what to do on Monday.", "sents": [[0.01, "Here's Evan's goal from the video, built one letter at a time.", 0], [4.35, "It's specific: partnership proposals from qualified vendors.", 1], [8.39, "And it's measurable because he can count three proposals.", 1], [11.71, "It's attainable since 60 days is enough to run a small selection process.", 2], [16.21, "And it's relevant, because a technical partner is exactly what his online community needs.", 2], [21.55, "And it's time-bound: within 60 days.", 3], [24.57, "A goal like this tells you what to do on Monday.", 3]], "v": "k1", "cues": [0.01, 4.35, 11.71, 21.55]}, "r2_code_pulse": {"dur": 7.36, "text": "Type the code from the last page of the Pulse Check, then select Submit. A quick knowledge check comes next, then your recap.", "sents": [[0.01, "Type the code from the last page of the Pulse Check, then select Submit.", 0], [4.23, "A quick knowledge check comes next, then your recap.", 0]], "v": "r3", "cues": [0.01]}, "r2_form_pulse": {"dur": 8.96, "text": "Answer the five questions, then select Submit. Your code appears on the last page. Copy the code or write it down, then select Next.", "sents": [[0, "Answer the five questions, then select Submit.", 0], [3.25, "Your code appears on the last page.", 0], [5.45, "Copy the code or write it down, then select Next.", 0]], "v": "r3", "cues": [0]}, "r2_pulse": {"dur": 21.36, "text": "Every lesson has the same short Pulse Check, a check-in that helps you see how you're changing over the season. It asks how often you've practiced each of the Core 4 and completed your reps in the last two weeks. It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing. Select Next, and it opens right here.", "sents": [[0.01, "Every lesson has the same short Pulse Check, a check-in that helps you see how you're changing over the season.", 0], [6.57, "It asks how often you've practiced each of the Core 4 and completed your reps in the last two weeks.", 1], [12.25, "It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing.", 2], [18.83, "Select Next, and it opens right here.", 2]], "v": "k1", "cues": [0.01, 6.57, 12.25]}};
